// Exact bounded polygon model. No browser or side effects.
const own=(o,keys)=>{if(!o||typeof o!=='object'||Array.isArray(o))return false;const d=Object.getOwnPropertyDescriptors(o);return Reflect.ownKeys(d).length===keys.length&&keys.every(k=>d[k]&&'value'in d[k]);};
export const presets={rectangle:[[0,0],[100,0],[100,100],[0,100]],triangle:[[0,0],[100,0],[0,100]],concave:[[0,0],[100,0],[100,40],[40,40],[40,100],[0,100]],twelve:[[25,0],[50,0],[75,0],[100,25],[100,50],[100,75],[75,100],[50,100],[25,100],[0,75],[0,50],[0,25]]};
export const rawVertices=k=>presets[k].map(([x,y])=>({xRaw:String(x),yRaw:String(y)}));
export const initialRaw=()=>({widthRaw:'240',heightRaw:'160',pattern:'checker',vertices:rawVertices('rectangle')});
export function parseRaw(raw,coordinate=true){if(typeof raw!=='string')return{error:'SCHEMA'};if(raw.length>32)return{error:'LENGTH'};const s=raw.replace(/^[\t\n\r ]+|[\t\n\r ]+$/g,'');if(!s)return{error:'EMPTY'};if(!(coordinate?/^(?:0|[1-9][0-9]*)(?:\.[0-9]{1,2})?$/:/^[1-9][0-9]*$/).test(s))return{error:'GRAMMAR'};const [a,b='']=s.split('.');const v=coordinate?BigInt(a)*100n+BigInt(b.padEnd(2,'0')):BigInt(s);if(coordinate?v>10000n:v<40n||v>800n)return{error:'RANGE'};return{value:v};}
export const orient=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
const min=(a,b)=>a<b?a:b,max=(a,b)=>a>b?a:b;
const on=(a,b,c)=>orient(a,b,c)===0n&&c[0]>=min(a[0],b[0])&&c[0]<=max(a[0],b[0])&&c[1]>=min(a[1],b[1])&&c[1]<=max(a[1],b[1]);
export function segment(a,b,c,d){const o1=orient(a,b,c),o2=orient(a,b,d),o3=orient(c,d,a),o4=orient(c,d,b);if(o1*o2<0n&&o3*o4<0n)return'CROSS';if([o1,o2,o3,o4].every(o=>o===0n)){const k=a[0]===b[0]?1:0,l=max(min(a[k],b[k]),min(c[k],d[k])),h=min(max(a[k],b[k]),max(c[k],d[k]));return l>h?null:l===h?'TOUCH':'OVERLAP';}return(o1===0n&&on(a,b,c))||(o2===0n&&on(a,b,d))||(o3===0n&&on(c,d,a))||(o4===0n&&on(c,d,b))?'TOUCH':null;}
export function topology(p){const n=p.length;for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(p[i][0]===p[j][0]&&p[i][1]===p[j][1])return{error:'DUPLICATE',indices:[i,j]};const S=p.reduce((s,a,i)=>s+a[0]*p[(i+1)%n][1]-p[(i+1)%n][0]*a[1],0n);if(S===0n)return{error:'ZERO_AREA',indices:p.map((_,i)=>i)};for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){if(j!==i+1&&!(i===0&&j===n-1))continue;const [a,b,c]=j===i+1?[p[i],p[j],p[(j+1)%n]]:[p[n-1],p[0],p[1]];if(orient(a,b,c)===0n&&(a[0]-b[0])*(c[0]-b[0])+(a[1]-b[1])*(c[1]-b[1])>=0n)return{error:'ADJACENT_OVERLAP',edges:[i,j],indices:[...new Set([i,(i+1)%n,j,(j+1)%n])].sort((a,b)=>a-b)};}
for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){if(j===i+1||i===0&&j===n-1)continue;const error=segment(p[i],p[(i+1)%n],p[j],p[(j+1)%n]);if(error)return{error,edges:[i,j],indices:[...new Set([i,(i+1)%n,j,(j+1)%n])].sort((a,b)=>a-b)};}return{S};}
const abs=n=>n<0n?-n:n;
export function fraction(n,d=1n){if(d<0n){n=-n;d=-d}if(!d)throw Error('zero denominator');let a=abs(n),b=d;while(b){[a,b]=[b,a%b]}return{n:n/a,d:d/a};}
export const exact=f=>f.d===1n?String(f.n):`${f.n}/${f.d}`;
export function approx(f){let q=abs(f.n)*1000n/f.d,r=abs(f.n)*1000n%f.d;if(r*2n>=f.d)q++;return`${f.n<0n&&q?'-':''}${q/1000n}.${String(q%1000n).padStart(3,'0')}`;}
export const canonical=q=>`${q/100n}${q%100n?'.'+String(q%100n).padStart(2,'0').replace(/0+$/,''):''}`;
export function calculate(raw){if(!own(raw,['widthRaw','heightRaw','pattern','vertices'])||!['checker','diagonal'].includes(raw.pattern)||!Array.isArray(raw.vertices)||raw.vertices.length<3||raw.vertices.length>12)return{error:'SCHEMA',field:'widthRaw',indices:[]};const vd=Object.getOwnPropertyDescriptors(raw.vertices);if(Reflect.ownKeys(vd).length!==raw.vertices.length+1||!Array.from({length:raw.vertices.length},(_,i)=>vd[i]&&'value'in vd[i]).every(Boolean))return{error:'SCHEMA',field:'widthRaw',indices:[]};for(let i=0;i<raw.vertices.length;i++)if(!own(raw.vertices[i],['xRaw','yRaw'])||typeof raw.vertices[i].xRaw!=='string'||typeof raw.vertices[i].yRaw!=='string')return{error:'SCHEMA',field:`${i}:xRaw`,indices:[i]};if(typeof raw.widthRaw!=='string'||typeof raw.heightRaw!=='string')return{error:'SCHEMA',field:'widthRaw',indices:[]};
const vals=[];for(const key of ['widthRaw','heightRaw']){const a=parseRaw(raw[key],false);if(a.error)return{...a,field:key,indices:[]};vals.push(a.value);}const p=[];for(let i=0;i<raw.vertices.length;i++){const v=[];for(const key of ['xRaw','yRaw']){const a=parseRaw(raw.vertices[i][key]);if(a.error)return{...a,field:`${i}:${key}`,indices:[i]};v.push(a.value);}p.push(v);}const t=topology(p);if(t.error)return{...t,field:`${t.indices[0]}:xRaw`};const[W,H]=vals,S=t.S;const bounds=[p.reduce((s,v)=>min(s,v[0]),10000n),p.reduce((s,v)=>min(s,v[1]),10000n),p.reduce((s,v)=>max(s,v[0]),0n),p.reduce((s,v)=>max(s,v[1]),0n)];const css=`clip-path: polygon(nonzero, ${p.map(v=>v.map(q=>canonical(q)+'%').join(' ')).join(', ')}) border-box;\n`;return Object.freeze({W,H,pattern:raw.pattern,points:p,S,winding:S>0n?'clockwise':'counterclockwise',pixels:p.map(v=>[fraction(W*v[0],10000n),fraction(H*v[1],10000n)]),area:fraction(abs(S)*W*H,200000000n),coverage:fraction(abs(S),2000000n),bounds,boundsPx:bounds.map((q,i)=>fraction(q*(i%2?H:W),10000n)),css});}
export const initialState=()=>({raw:initialRaw(),selected:0,locale:'zh',status:'initial',result:null,error:null});
const dirty=(s,raw,selected=s.selected)=>({...s,raw,selected,status:'dirty',result:null,error:null});
export function reduce(s,a){if(a.type==='language')return{...s,locale:a.locale};if(a.type==='select')return{...s,selected:a.index};if(a.type==='reset')return{...initialState(),locale:s.locale};if(a.type==='invalidate')return dirty(s,s.raw);if(a.type==='edit'){const raw={...s.raw,vertices:s.raw.vertices.map(v=>({...v}))};if(a.index===undefined)raw[a.field]=a.value;else raw.vertices[a.index][a.field]=a.value;return dirty(s,raw);}if(a.type==='preset')return dirty(s,{...s.raw,vertices:rawVertices(a.preset)},0);if(a.type==='add'){if(s.raw.vertices.length===12)return s;const vs=s.raw.vertices.map(v=>({...v}));vs.splice(s.selected+1,0,{xRaw:'',yRaw:''});return dirty(s,{...s.raw,vertices:vs},s.selected+1);}if(a.type==='remove'){if(s.raw.vertices.length===3)return s;const vs=s.raw.vertices.filter((_,i)=>i!==s.selected);return dirty(s,{...s.raw,vertices:vs},Math.min(s.selected,vs.length-1));}if(a.type==='generate'){try{const r=calculate(s.raw);return r.error?{...s,status:'error',result:null,error:r}:{...s,status:'generated',result:r,error:null};}catch{return{...s,status:'error',result:null,error:{error:'INTERNAL',indices:[],field:'widthRaw'}};}}return s;}
